import{_ as d,c as r,o as a,ae as l}from"./chunks/framework.BvcDoAct.js";const b=JSON.parse('{"title":"术语与风格指南（Style Guide）","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/prompts/style_guide.md","filePath":"scripts/prompts/style_guide.md"}'),o={name:"scripts/prompts/style_guide.md"};function i(e,t,n,h,s,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="术语与风格指南-style-guide" tabindex="-1">术语与风格指南（Style Guide） <a class="header-anchor" href="#术语与风格指南-style-guide" aria-label="Permalink to &quot;术语与风格指南（Style Guide）&quot;">​</a></h1><blockquote><p>适用范围：BE:FIRST 访谈系列全书（含引言、成员个人访谈、后续增补章）的翻译（Translation）/ 编辑（Editing）/ 校对（Proofreading）。</p><p>目标：统一专名与术语、稳定采访叙事语感、保留成员个体人格与现场感，避免“日式直译腔”“网文夸饰腔”“公关稿平滑化”。</p></blockquote><hr><h2 id="_0-全局执行原则-global-principles" tabindex="-1">0. 全局执行原则（Global Principles） <a class="header-anchor" href="#_0-全局执行原则-global-principles" aria-label="Permalink to &quot;0. 全局执行原则（Global Principles）&quot;">​</a></h2><ol><li><strong>专名唯一制</strong>：同一实体仅保留一个主译名（必要时首现并列原文）。</li><li><strong>语义优先于字面</strong>：先还原说话意图，再落地为自然中文口语。</li><li><strong>采访体优先</strong>：保留停顿、犹豫、自我修正、重复，不改写成“书面演讲稿”。</li><li><strong>人物区分必须可感知</strong>：记者与成员、成员与成员之间语气不能混同。</li><li><strong>专业词不降级</strong>：音乐制作/舞蹈术语保持行业精度，首现可做短注。</li><li><strong>时间轴一致</strong>：围绕“2021 出道 → 4 周年 → 5 年目/5 周年节点 → 未来展望”统一表述。</li><li><strong>“真实感”高于“文采感”</strong>：允许不那么工整，但必须像人在说话。</li></ol><hr><h2 id="_1-人名与专有名词对照表-name-proper-noun-glossary" tabindex="-1">1. 人名与专有名词对照表（Name &amp; Proper Noun Glossary） <a class="header-anchor" href="#_1-人名与专有名词对照表-name-proper-noun-glossary" aria-label="Permalink to &quot;1. 人名与专有名词对照表（Name &amp; Proper Noun Glossary）&quot;">​</a></h2><h3 id="_1-1-成员与人物" tabindex="-1">1.1 成员与人物 <a class="header-anchor" href="#_1-1-成员与人物" aria-label="Permalink to &quot;1.1 成员与人物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原写法</th><th>统一中文译名</th><th>说明</th></tr></thead><tbody><tr><td>SOTA</td><td>SOTA</td><td>成员名保留官方罗马字</td></tr><tr><td>SHUNTO</td><td>SHUNTO</td><td>同上</td></tr><tr><td>MANATO</td><td>MANATO</td><td>同上</td></tr><tr><td>RYUHEI</td><td>RYUHEI</td><td>同上</td></tr><tr><td>JUNON</td><td>JUNON</td><td>同上</td></tr><tr><td>LEO</td><td>LEO</td><td>同上</td></tr><tr><td>RYOKI</td><td>RYOKI</td><td>若后文章节出现，沿用同规则</td></tr><tr><td>SKY-HI</td><td>SKY-HI</td><td>不汉化、不意译</td></tr><tr><td>RIEHATA</td><td>RIEHATA</td><td>舞者/编舞师名保留</td></tr><tr><td>小川智宏</td><td>小川智宏</td><td>采访者</td></tr><tr><td>安田季那子</td><td>安田季那子</td><td>撰稿署名</td></tr><tr><td>大野隼男</td><td>大野隼男</td><td>摄影</td></tr><tr><td>上村礼王</td><td>上村礼王</td><td>LEO 本名（仅在语义必要时使用）</td></tr><tr><td>Nissy</td><td>Nissy</td><td>艺名保留</td></tr><tr><td>Michael Jackson / マイケル・ジャクソン</td><td>迈克尔·杰克逊</td><td>常规中文译名</td></tr><tr><td>Jackson 5 / ジャクソン5</td><td>杰克逊五人组</td><td>首现可并列 Jackson 5</td></tr></tbody></table><h3 id="_1-2-团体、公司、企划、媒体" tabindex="-1">1.2 团体、公司、企划、媒体 <a class="header-anchor" href="#_1-2-团体、公司、企划、媒体" aria-label="Permalink to &quot;1.2 团体、公司、企划、媒体&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原写法</th><th>统一中文译名</th><th>说明</th></tr></thead><tbody><tr><td>BE:FIRST</td><td>BE:FIRST</td><td>团名不翻译</td></tr><tr><td>BMSG</td><td>BMSG</td><td>公司/厂牌名不翻译</td></tr><tr><td>THE FIRST</td><td>《THE FIRST》</td><td>选秀企划，按作品处理</td></tr><tr><td>MAZZEL</td><td>MAZZEL</td><td>团名不翻译</td></tr><tr><td>AAA</td><td>AAA</td><td>组合名保留原文</td></tr><tr><td>ATEEZ</td><td>ATEEZ</td><td>组合名保留原文</td></tr><tr><td>ROCK IN JAPAN FESTIVAL</td><td>ROCK IN JAPAN FESTIVAL</td><td>音乐节名保留</td></tr><tr><td>THE FIRST TAKE</td><td>THE FIRST TAKE</td><td>栏目/平台名保留</td></tr><tr><td>JAPAN（刊物语境）</td><td>《rockin&#39;on JAPAN》</td><td>明确指杂志时使用</td></tr><tr><td>BFLAB</td><td>BFLAB</td><td>项目名保留（必要时首现加注“企划名”）</td></tr></tbody></table><h3 id="_1-3-作品、曲目、巡演、活动" tabindex="-1">1.3 作品、曲目、巡演、活动 <a class="header-anchor" href="#_1-3-作品、曲目、巡演、活动" aria-label="Permalink to &quot;1.3 作品、曲目、巡演、活动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原写法</th><th>统一中文译名</th><th>说明</th></tr></thead><tbody><tr><td>BE:ST</td><td>《BE:ST》</td><td>最佳专辑</td></tr><tr><td>BE:1</td><td>《BE:1》</td><td>专辑</td></tr><tr><td>Scream</td><td>《Scream》</td><td>曲名</td></tr><tr><td>Mainstream</td><td>《Mainstream》</td><td>曲名</td></tr><tr><td>Boom Boom Back</td><td>《Boom Boom Back》</td><td>曲名</td></tr><tr><td>Stay Strong</td><td>《Stay Strong》</td><td>曲名</td></tr><tr><td>Bye-Good-Bye</td><td>《Bye-Good-Bye》</td><td>曲名</td></tr><tr><td>Shining One</td><td>《Shining One》</td><td>曲名</td></tr><tr><td>Be Free</td><td>《Be Free》</td><td>曲名</td></tr><tr><td>Move On</td><td>《Move On》</td><td>曲名</td></tr><tr><td>Gifted.</td><td>《Gifted.》</td><td>句点属于歌名本体，须保留</td></tr><tr><td>I Want You Back</td><td>《I Want You Back》</td><td>本项目语境多为“重制翻唱版”</td></tr><tr><td>プラスティック・ラブ</td><td>《Plastic Love》</td><td>常用英文曲名</td></tr><tr><td>WIND BREAKER/ウィンドブレイカー</td><td>《WIND BREAKER/防风少年》</td><td>首现可并列；后文可简为《WIND BREAKER》</td></tr><tr><td>BMSG FES&#39;25</td><td>BMSG FES&#39;25</td><td>活动名保留</td></tr><tr><td>Dome Tour</td><td>巨蛋巡演</td><td>类型中文化</td></tr><tr><td>World Tour</td><td>世界巡演</td><td>类型中文化</td></tr><tr><td>Stadium公演</td><td>体育场公演</td><td>统一“公演”</td></tr><tr><td>ファンミーティング</td><td>粉丝见面会</td><td>首现可加（Fan Meeting）</td></tr><tr><td>ホールツアー</td><td>Hall 巡演</td><td>或“剧场巡演”，全章统一一种</td></tr></tbody></table><hr><h2 id="_2-核心黑话与业界术语-jargon-industry-terms" tabindex="-1">2. 核心黑话与业界术语（Jargon &amp; Industry Terms） <a class="header-anchor" href="#_2-核心黑话与业界术语-jargon-industry-terms" aria-label="Permalink to &quot;2. 核心黑话与业界术语（Jargon &amp; Industry Terms）&quot;">​</a></h2><blockquote><p>规则：首次出现采用“术语（中文解释）”；后续可直接用术语。避免全部俗化导致信息损失。</p></blockquote><table tabindex="0"><thead><tr><th>原术语</th><th>推荐译法</th><th>使用说明</th></tr></thead><tbody><tr><td>DTM</td><td>DTM（电脑音乐制作）</td><td>首现注释即可</td></tr><tr><td>キック</td><td>底鼓（Kick）</td><td>节奏制作语境</td></tr><tr><td>ハイハット</td><td>踩镲（Hi-hat）</td><td>同上</td></tr><tr><td>フック</td><td>Hook（副歌钩子段）</td><td>不译“钩子句”</td></tr><tr><td>ヴァース</td><td>Verse（主歌段）</td><td>与 Hook 对应</td></tr><tr><td>トラック</td><td>伴奏 / 轨道（Track）</td><td>按上下文二选一</td></tr><tr><td>ミックス</td><td>混音（Mix）</td><td>固定译法</td></tr><tr><td>サンプリング</td><td>采样（Sampling）</td><td>音源引用语境</td></tr><tr><td>リレコーディング</td><td>重录</td><td></td></tr><tr><td>リメイクカバー</td><td>重制翻唱</td><td>区别于纯翻唱</td></tr><tr><td>リスペクトカバー</td><td>致敬翻唱</td><td>强调“致敬”动机</td></tr><tr><td>セトリ（セットリスト）</td><td>歌单编排（Setlist）</td><td>演出语境</td></tr><tr><td>ディグる</td><td>挖歌 / 深挖音乐</td><td>口语，不用“发掘音乐资料”</td></tr><tr><td>フロア</td><td>舞池现场</td><td>club / battle 语境</td></tr><tr><td>バトル</td><td>Battle 对决</td><td>街舞语境</td></tr><tr><td>ポッピン</td><td>Popping（机械舞）</td><td>舞种名保留英文</td></tr><tr><td>サウス</td><td>南部风格（South）</td><td>嘻哈语境</td></tr><tr><td>フリースタイル</td><td>Freestyle（即兴）</td><td></td></tr><tr><td>コード</td><td>和弦（Chord）</td><td></td></tr><tr><td>小節</td><td>小节</td><td></td></tr><tr><td>マイナー</td><td>小调 / Minor</td><td>按句意选</td></tr><tr><td>シンセ</td><td>合成器音色（Synth）</td><td></td></tr><tr><td>クリック</td><td>节拍器点击音（Click）</td><td>录音/排练语境</td></tr><tr><td>生楽器</td><td>真乐器 / 原声乐器</td><td>与电子音色对照</td></tr><tr><td>立ち位置</td><td>角色定位</td><td>团队分工语境</td></tr><tr><td>バランサー</td><td>平衡位 / 平衡型成员</td><td>禁译“平衡器”</td></tr><tr><td>アティチュード</td><td>态度感 / 态度</td><td>音乐人格语境</td></tr><tr><td>アーティシズム</td><td>艺术性 / 艺术取向</td><td>结合上下文落地</td></tr><tr><td>バックボーン</td><td>背景支撑 / 根基</td><td>语气可偏抽象</td></tr><tr><td>バイブス</td><td>氛围张力 / vibe</td><td>保留口语感</td></tr><tr><td>エモい</td><td>很有情绪张力 / 很戳</td><td>禁僵硬“感性化”</td></tr><tr><td>しっくりハマる</td><td>完全卡上 / 特别对位</td><td>口语优先</td></tr></tbody></table><h3 id="_2-1-本项目高频抽象词固定译法" tabindex="-1">2.1 本项目高频抽象词固定译法 <a class="header-anchor" href="#_2-1-本项目高频抽象词固定译法" aria-label="Permalink to &quot;2.1 本项目高频抽象词固定译法&quot;">​</a></h3><ul><li>進化 → <strong>进化</strong>（不随意替换“升级”）</li><li>覚悟 → <strong>觉悟 / 决心</strong>（按强度选）</li><li>貪欲 → <strong>有野心 / 够贪心（正向）</strong></li><li>自然体 → <strong>自然状态 / 不端着</strong></li><li>等身大 → <strong>贴近当下自身状态 / 不端着的真实尺度</strong></li><li>背伸び → <strong>有点硬撑 / 超阶段拔高</strong></li><li>刺さる → <strong>打中人 / 直戳人心</strong></li><li>俯瞰で見る → <strong>从整体视角看 / 俯瞰地看</strong></li><li>しがらみ → <strong>束缚感 / 框架压力</strong></li></ul><hr><h2 id="_3-文风与语气设定规范-tone-voice" tabindex="-1">3. 文风与语气设定规范（Tone &amp; Voice） <a class="header-anchor" href="#_3-文风与语气设定规范-tone-voice" aria-label="Permalink to &quot;3. 文风与语气设定规范（Tone &amp; Voice）&quot;">​</a></h2><h3 id="_3-1-叙述层级-记者-vs-成员" tabindex="-1">3.1 叙述层级：记者 vs 成员 <a class="header-anchor" href="#_3-1-叙述层级-记者-vs-成员" aria-label="Permalink to &quot;3.1 叙述层级：记者 vs 成员&quot;">​</a></h3><ol><li><p><strong>记者（小川智宏）</strong></p><ul><li>语感：观察细、逻辑推进强、常“先确认再追问”。</li><li>中文落地：句子完整清晰，偏理性，不用网络化夸张词。</li><li>常见结构： <ul><li><code>你刚才提到……这是否意味着……？</code></li><li><code>换句话说……可以这样理解吗？</code></li></ul></li></ul></li><li><p><strong>成员回答</strong></p><ul><li>语感：口语、实时思考、边说边修正、常带笑场与自嘲。</li><li>中文落地：短句+转折+停顿，允许“嗯、其实、怎么说呢”。</li><li>禁止：过度抛光成“标准采访金句合集”。</li></ul></li></ol><h3 id="_3-2-成员个体语气画像-必须区分" tabindex="-1">3.2 成员个体语气画像（必须区分） <a class="header-anchor" href="#_3-2-成员个体语气画像-必须区分" aria-label="Permalink to &quot;3.2 成员个体语气画像（必须区分）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>成员</th><th>原文语感</th><th>中文映射策略</th></tr></thead><tbody><tr><td>SOTA</td><td>技术词密集、兴奋度高、节奏快、跨舞蹈与制作</td><td>用“专业+燃感”并行；术语可直给，句子不要太书面</td></tr><tr><td>SHUNTO</td><td>自省、讲分寸、强调控制与平衡</td><td>用词克制、逻辑清楚，少口号，多“我在调整”</td></tr><tr><td>MANATO</td><td>结构化思维强、俯瞰团队机制、计划导向</td><td>语气稳、判断准，突出“策略视角/系统视角”</td></tr><tr><td>RYUHEI</td><td>年轻但思辨强、野心感与探索欲并存</td><td>保留“少年感+野心感”；避免翻成成熟社论腔</td></tr><tr><td>JUNON</td><td>温和谦逊、聚焦“歌”、表达简洁</td><td>中文要干净笃定，少修饰，强调“声音与现场传达”</td></tr><tr><td>LEO</td><td>外向热情与内在自我否定并存，反差强</td><td>保留“先自嘲后认真”的真诚转折，情绪起伏可见</td></tr></tbody></table><h3 id="_3-3-口语标记词转换表" tabindex="-1">3.3 口语标记词转换表 <a class="header-anchor" href="#_3-3-口语标记词转换表" aria-label="Permalink to &quot;3.3 口语标记词转换表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日文口语</th><th>推荐中文</th><th>禁忌</th></tr></thead><tbody><tr><td>めっちゃ</td><td>特别 / 非常 / 真的很</td><td>全部译“超级”</td></tr><tr><td>マジで</td><td>真的 / 说真的</td><td>频繁译“老实说”</td></tr><tr><td>〜っすね / 〜ですね</td><td>是啊 / 确实 / 我也是这么想</td><td>机械删除导致失真</td></tr><tr><td>どうだろう</td><td>这个嘛 / 不好说</td><td>硬译“如何呢”</td></tr><tr><td>〜かな</td><td>可能吧 / 我觉得</td><td>全删会丢失未定感</td></tr><tr><td>いや</td><td>不过 / 其实 / 倒也不是</td><td>全译“不是”显生硬</td></tr><tr><td>うーん</td><td>嗯…… / 这个……</td><td>直接删掉犹豫层</td></tr></tbody></table><h3 id="_3-4-礼貌层与称呼" tabindex="-1">3.4 礼貌层与称呼 <a class="header-anchor" href="#_3-4-礼貌层与称呼" aria-label="Permalink to &quot;3.4 礼貌层与称呼&quot;">​</a></h3><ul><li>日文敬语不逐字迁移为中文敬语套话。</li><li>礼貌感通过“语气柔和+句式完整”体现，不堆叠“您/非常感谢您/请允许我”。</li><li>成员感谢场景可直译“谢谢/很感激”，非感谢场景不额外加礼貌词。</li></ul><h3 id="_3-5-引语与情绪标记" tabindex="-1">3.5 引语与情绪标记 <a class="header-anchor" href="#_3-5-引语与情绪标记" aria-label="Permalink to &quot;3.5 引语与情绪标记&quot;">​</a></h3><ul><li>直接引语统一全角引号「」。</li><li>重点语句可保留 <strong>加粗</strong>（对应原文强调）。</li><li>（笑）（苦笑）（停顿）可保留，但仅在确实影响语气判断时使用。</li></ul><hr><h2 id="_4-句法与版式规范-syntax-formatting" tabindex="-1">4. 句法与版式规范（Syntax &amp; Formatting） <a class="header-anchor" href="#_4-句法与版式规范-syntax-formatting" aria-label="Permalink to &quot;4. 句法与版式规范（Syntax &amp; Formatting）&quot;">​</a></h2><ol><li><strong>长句重组</strong>：日文多层修饰按“主干 → 补充”拆译。</li><li><strong>主语补足</strong>：对省略主语按语境补“我/我们/成员/团队/公司”。</li><li><strong>逻辑显化</strong>：必要时补“所以/但/同时/换句话说”。</li><li><strong>并列对齐</strong>：并列项词性一致（如“唱、跳、制作”）。</li><li><strong>标点统一</strong>：中文全角标点；省略号“……”；破折号“——”。</li><li><strong>中英数字空格</strong>：中文与英文/数字间留空格（如“5 周年”“World Tour”）。</li><li><strong>曲名与书名号</strong>：作品统一《》；英文曲名保留大小写与标点本体。</li><li><strong>问答排版</strong>：建议保留“● 提问 / 「回答」”结构，确保采访节奏可见。</li></ol><hr><h2 id="_5-常见误译与风险点-do-don-t" tabindex="-1">5. 常见误译与风险点（Do / Don’t） <a class="header-anchor" href="#_5-常见误译与风险点-do-don-t" aria-label="Permalink to &quot;5. 常见误译与风险点（Do / Don’t）&quot;">​</a></h2><h3 id="_5-1-禁止项-don-t" tabindex="-1">5.1 禁止项（Don’t） <a class="header-anchor" href="#_5-1-禁止项-don-t" aria-label="Permalink to &quot;5.1 禁止项（Don’t）&quot;">​</a></h3><ol><li>不将成员名汉化（如“俊斗”“怜欧”）。</li><li>不把采访体改成新闻播报或品牌公关文。</li><li>不把术语全部降维成泛词（如全部译“节奏”“感觉”）。</li><li>不清洗全部口头禅（会丢人物识别度）。</li><li>不过度文学化（比喻堆叠、抒情泛滥）。</li></ol><h3 id="_5-2-必做项-do" tabindex="-1">5.2 必做项（Do） <a class="header-anchor" href="#_5-2-必做项-do" aria-label="Permalink to &quot;5.2 必做项（Do）&quot;">​</a></h3><ol><li>保留“自我修正”轨迹（如“也不是说……只是……”）。</li><li>保留“反差人格”信息（尤其 LEO、SHUNTO、RYUHEI）。</li><li>在技术段落维持术语密度（尤其 SOTA、制作相关段落）。</li><li>将“抽象表达”落到可读中文，但不抹平抽象感。</li></ol><hr><h2 id="_6-术语冲突裁决-conflict-resolution" tabindex="-1">6. 术语冲突裁决（Conflict Resolution） <a class="header-anchor" href="#_6-术语冲突裁决-conflict-resolution" aria-label="Permalink to &quot;6. 术语冲突裁决（Conflict Resolution）&quot;">​</a></h2><p>出现多译法冲突时，按优先级决策：</p><ol><li>官方表记（艺名/团名/作品名）</li><li>本指南既定译法</li><li>音乐行业通行译法</li><li>语境可读性最优解（并在首现加注）</li></ol><hr><h2 id="_7-可复用执行模板-operational-templates" tabindex="-1">7. 可复用执行模板（Operational Templates） <a class="header-anchor" href="#_7-可复用执行模板-operational-templates" aria-label="Permalink to &quot;7. 可复用执行模板（Operational Templates）&quot;">​</a></h2><h3 id="_7-1-首次出现模板" tabindex="-1">7.1 首次出现模板 <a class="header-anchor" href="#_7-1-首次出现模板" aria-label="Permalink to &quot;7.1 首次出现模板&quot;">​</a></h3><ul><li>人名首现：<code>LEO（上村礼王）</code>（仅在语义必要时）</li><li>术语首现：<code>DTM（电脑音乐制作）</code></li><li>作品首现：<code>《WIND BREAKER/防风少年》</code></li></ul><h3 id="_7-2-记者追问模板" tabindex="-1">7.2 记者追问模板 <a class="header-anchor" href="#_7-2-记者追问模板" aria-label="Permalink to &quot;7.2 记者追问模板&quot;">​</a></h3><ul><li><code>你刚提到……，那这是否意味着……？</code></li><li><code>回头看当时的发言，你现在会怎么理解？</code></li></ul><h3 id="_7-3-成员口语承接模板" tabindex="-1">7.3 成员口语承接模板 <a class="header-anchor" href="#_7-3-成员口语承接模板" aria-label="Permalink to &quot;7.3 成员口语承接模板&quot;">​</a></h3><ul><li><code>对，我现在会更……。</code></li><li><code>也不是说完全……，但至少……。</code></li><li><code>这个很难一句话说清，不过我会觉得……。</code></li></ul><hr><h2 id="_8-终稿质检清单-qa-checklist" tabindex="-1">8. 终稿质检清单（QA Checklist） <a class="header-anchor" href="#_8-终稿质检清单-qa-checklist" aria-label="Permalink to &quot;8. 终稿质检清单（QA Checklist）&quot;">​</a></h2><ul><li>[ ] 人名/团名/作品名是否全文 100% 一致</li><li>[ ] 同一术语是否出现多种译法</li><li>[ ] 记者与成员语气是否可一眼区分</li><li>[ ] 六位成员语气是否各自可辨识</li><li>[ ] 是否存在明显“日式被动句/长定语堆积”</li><li>[ ] 是否误删关键口语标记（犹豫、转折、自嘲）</li><li>[ ] 技术段落是否保持专业度而非被口水化</li><li>[ ] 标点、空格、书名号、引号是否统一</li></ul><hr><p><strong>本文件为本项目全局最高规范。后续 Translation / Editing / Proofreading 如有冲突，一律以本指南为准。</strong></p>',57)])])}const g=d(o,[["render",i]]);export{b as __pageData,g as default};
